def process(serous_variants) -> pd.DataFrame:
    import numpy as np
    import pandas as pd

    vals = pd.to_numeric(serous_variants['variants_per_Mbp'], errors='coerce').dropna()
    med = float(np.median(vals))
    return pd.DataFrame([{
        'n_serous': int(vals.shape[0]),
        'median_variants_per_Mbp': med,
        'median_variants_per_Mbp_rounded4': round(med, 4)
    }])
